{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "summary_header_stack",
        "summary_description",
        "distribution_title",
        "distribution_intro",
        "coffee_table",
        "popular_title",
        "popular_text"
      ]
    },
    "summary_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "cup_icon",
        "summary_title"
      ]
    },
    "cup_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000541_01_1_cup-hot.svg"
      },
      "children": []
    },
    "summary_title": {
      "type": "Text",
      "props": {
        "text": "Coffee Preference Summary",
        "variant": "h2"
      },
      "children": []
    },
    "summary_description": {
      "type": "Text",
      "props": {
        "text": "This summary details the distribution of preferred coffee types based on the provided survey responses, helping to visualize popular choices."
      },
      "children": []
    },
    "distribution_title": {
      "type": "Text",
      "props": {
        "text": "Coffee Preference Distribution",
        "variant": "h3"
      },
      "children": []
    },
    "distribution_intro": {
      "type": "Text",
      "props": {
        "text": "The following data outlines the percentage breakdown of each coffee type from the survey."
      },
      "children": []
    },
    "coffee_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Coffee Type",
            "label": "Coffee Type"
          },
          {
            "key": "Percentage",
            "label": "Percentage"
          }
