        "rows": [
          {
            "Coffee Type": "Latte",
            "Percentage": 37.5
          },
          {
            "Coffee Type": "Espresso",
            "Percentage": 25.0
          },
          {
            "Coffee Type": "Cappuccino",
            "Percentage": 25.0
          },
          {
            "Coffee Type": "Americano",
            "Percentage": 12.5
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "Coffee Type",
        "highlightColumns": [
          "Percentage"
        ],
        "numericColumns": [
          "Percentage"
        ]
      },
      "children": []
    },
    "popular_title": {
      "type": "Text",
      "props": {
        "text": "Most Popular Coffee",
        "variant": "h3"
      },
      "children": []
    },
    "popular_text": {
      "type": "Text",
      "props": {
        "text": "Latte is the most preferred coffee type, representing 37.5% of all responses."
      },
      "children": []
    }
  }
